const CAT_PRESETS = [{"name": "r01-c01", "src": "data:image/png;base64,"}, {"name": "r01-c02", "src": "data:image/png;base64,"}, {"name": "r01-c03", "src": "data:image/png;base64,"}, {"name": "r01-c04", "src": "data:image/png;base64,"}, {"name": "r02-c01", "src": "data:image/png;base64,"}, {"name": "r02-c02", "src": "data:image/png;base64,"}, {"name": "r02-c03", "src": "data:image/png;base64,"}, {"name": "r02-c04", "src": "data:image/png;base64,"}, {"name": "r03-c01", "src": "data:image/png;base64,"}, {"name": "r03-c02", "src": "data:image/png;base64,"}, {"name": "r03-c03", "src": "data:image/png;base64,"}, {"name": "r03-c04", "src": "data:image/png;base64,"}, {"name": "r04-c01", "src": "data:image/png;base64,"}, {"name": "r04-c02", "src": "data:image/png;base64,"}, {"name": "r04-c03", "src": "data:image/png;base64,"}, {"name": "r04-c04", "src": "data:image/png;base64,"}];
const $ = (id) => document.getElementById(id);
const srcCanvas = $('srcCanvas'), outCanvas = $('outCanvas');
const srcCtx = srcCanvas.getContext('2d', { willReadFrequently:true });
const outCtx = outCanvas.getContext('2d', { willReadFrequently:true });
let currentImage = new Image();
let currentName = 'r02-c02';
let lastOutput = null;
let lastBits = null;
let lastWidth = 0;
let lastHeight = 0;

const notes = {
  'threshold': 'Fast and crisp. Good for text, QR codes, and high-contrast line art; bad for photos and subtle fur detail.',
  'adaptive-mean': 'Local threshold from a sliding neighborhood. Useful for uneven scans/line art; can amplify texture noise.',
  'bayer4': 'Tiny ordered threshold matrix. Stable and fast, but visibly patterned.',
  'bayer8': 'Larger ordered Bayer matrix. Better tones than 4x4, still a recognizable grid.',
  'blue-noise': 'Deterministic hash mask with high-frequency texture. Not a true void-and-cluster mask, but useful for testing non-grid ordered noise.',
  'floyd': 'Classic error diffusion. Good tone preservation; may create worms and too-dark thermal regions.',
  'atkinson': 'Mac-like lighter error diffusion. Often attractive on thermal paper and good for cat portraits.',
  'stucki': 'Smoother larger-kernel diffusion. Rich tone, slightly softer edges.',
  'burkes': 'Faster Stucki-like diffusion. Good compromise.',
  'sierra2': 'Two-row Sierra diffusion. Smooth but still fairly efficient.',
  'sierra-lite': 'Small Sierra kernel. Fast, light, and sometimes crisp.',
  'edge-hybrid': 'Atkinson tone layer plus Sobel edge recovery. Intended to preserve whiskers/eyes/outlines without blacking out the whole image.'
};

function controls() {
  return {
    algorithm: $('algorithm').value,
    maxWidth: +$('maxWidth').value,
    threshold: +$('threshold').value,
    brightness: +$('brightness').value,
    contrast: +$('contrast').value / 100,
    gamma: +$('gamma').value / 100,
    strength: +$('strength').value / 100,
    edgeThreshold: +$('edgeThreshold').value,
    feedLines: +$('feedLines').value,
  };
}
function updateLabels() {
  const c = controls();
  $('wVal').textContent = c.maxWidth + ' px'; $('tVal').textContent = c.threshold;
  $('bVal').textContent = c.brightness; $('cVal').textContent = c.contrast.toFixed(2) + 'x';
  $('gVal').textContent = c.gamma.toFixed(2); $('sVal').textContent = c.strength.toFixed(2) + 'x';
  $('eVal').textContent = c.edgeThreshold;
  $('fVal').textContent = $('feedLines').value;
  $('algoNote').textContent = notes[c.algorithm] || '';
}
function clamp(v, lo=0, hi=255) { return v < lo ? lo : v > hi ? hi : v; }
function luminance(r,g,b) { return 0.299*r + 0.587*g + 0.114*b; }
function tone(v, c) {
  v = v / 255;
  v = Math.pow(clamp(v,0,1), c.gamma);
  v = (v - 0.5) * c.contrast + 0.5 + c.brightness / 255;
  return clamp(v * 255);
}
function prepareGray(imgData, c) {
  const w = imgData.width, h = imgData.height, data = imgData.data;
  const gray = new Float32Array(w*h);
  for (let i=0, p=0; i<data.length; i+=4, p++) gray[p] = tone(luminance(data[i], data[i+1], data[i+2]), c);
  return gray;
}
function boolToImage(bits, w, h) {
  const im = outCtx.createImageData(w,h);
  let black = 0;
  for (let p=0; p<bits.length; p++) {
    const v = bits[p] ? 0 : 255; if (bits[p]) black++;
    const i=p*4; im.data[i]=im.data[i+1]=im.data[i+2]=v; im.data[i+3]=255;
  }
  return { imageData: im, black };
}
const bayer4 = [0,8,2,10,12,4,14,6,3,11,1,9,15,7,13,5];
const bayer8 = [0,48,12,60,3,51,15,63,32,16,44,28,35,19,47,31,8,56,4,52,11,59,7,55,40,24,36,20,43,27,39,23,2,50,14,62,1,49,13,61,34,18,46,30,33,17,45,29,10,58,6,54,9,57,5,53,42,26,38,22,41,25,37,21];
function hashNoise(x,y) {
  let n = (x*374761393 + y*668265263) ^ ((x+y)*2246822519); n = (n ^ (n>>>13)) * 1274126177; n = (n ^ (n>>>16)) >>> 0; return n & 255;
}
function threshold(gray,w,h,c) { const bits=new Uint8Array(w*h); for(let i=0;i<bits.length;i++) bits[i]=gray[i] < c.threshold; return bits; }
function ordered(gray,w,h,c,mat,n) {
  const bits=new Uint8Array(w*h); const amp=96*c.strength;
  for(let y=0;y<h;y++) for(let x=0;x<w;x++) { const m=mat[(y%n)*n+(x%n)]/(n*n-1); const t=c.threshold + (m-0.5)*amp; bits[y*w+x]=gray[y*w+x] < t; }
  return bits;
}
function blueNoise(gray,w,h,c) {
  const bits=new Uint8Array(w*h); const amp=110*c.strength;
  for(let y=0;y<h;y++) for(let x=0;x<w;x++) { const m=hashNoise(x,y)/255; const t=c.threshold + (m-0.5)*amp; bits[y*w+x]=gray[y*w+x] < t; }
  return bits;
}
function adaptiveMean(gray,w,h,c) {
  const bits=new Uint8Array(w*h), r=8, bias=c.threshold-128;
  for(let y=0;y<h;y++) for(let x=0;x<w;x++) {
    let sum=0, count=0;
    for(let yy=Math.max(0,y-r); yy<=Math.min(h-1,y+r); yy++) for(let xx=Math.max(0,x-r); xx<=Math.min(w-1,x+r); xx++) { sum += gray[yy*w+xx]; count++; }
    bits[y*w+x] = gray[y*w+x] < (sum/count + bias);
  }
  return bits;
}
const kernels = {
  floyd: { div:16, taps:[[1,0,7],[-1,1,3],[0,1,5],[1,1,1]] },
  atkinson: { div:8, taps:[[1,0,1],[2,0,1],[-1,1,1],[0,1,1],[1,1,1],[0,2,1]] },
  stucki: { div:42, taps:[[1,0,8],[2,0,4],[-2,1,2],[-1,1,4],[0,1,8],[1,1,4],[2,1,2],[-2,2,1],[-1,2,2],[0,2,4],[1,2,2],[2,2,1]] },
  burkes: { div:32, taps:[[1,0,8],[2,0,4],[-2,1,2],[-1,1,4],[0,1,8],[1,1,4],[2,1,2]] },
  sierra2: { div:16, taps:[[1,0,4],[2,0,3],[-2,1,1],[-1,1,2],[0,1,3],[1,1,2],[2,1,1]] },
  'sierra-lite': { div:4, taps:[[1,0,2],[-1,1,1],[0,1,1]] },
};
function diffuse(gray,w,h,c,kernelName) {
  const k = kernels[kernelName], work = new Float32Array(gray), bits = new Uint8Array(w*h);
  for(let y=0;y<h;y++) for(let x=0;x<w;x++) {
    const idx=y*w+x, old=work[idx], black=old < c.threshold, newv=black?0:255; bits[idx]=black;
    const err=(old-newv)*c.strength;
    for(const [dx,dy,wt] of k.taps) { const nx=x+dx, ny=y+dy; if(nx>=0&&nx<w&&ny>=0&&ny<h) work[ny*w+nx] += err*wt/k.div; }
  }
  return bits;
}
function sobelEdges(gray,w,h,c) {
  const e = new Uint8Array(w*h);
  for(let y=1;y<h-1;y++) for(let x=1;x<w-1;x++) {
    const i=y*w+x;
    const gx = -gray[i-w-1] -2*gray[i-1] -gray[i+w-1] + gray[i-w+1] +2*gray[i+1] + gray[i+w+1];
    const gy = -gray[i-w-1] -2*gray[i-w] -gray[i-w+1] + gray[i+w-1] +2*gray[i+w] + gray[i+w+1];
    const mag = Math.sqrt(gx*gx+gy*gy);
    if(mag > c.edgeThreshold && gray[i] < 238) e[i]=1;
  }
  return e;
}
function edgeHybrid(gray,w,h,c) {
  const bits = diffuse(gray,w,h,c,'atkinson'); const edges=sobelEdges(gray,w,h,c);
  for(let i=0;i<bits.length;i++) if(edges[i]) bits[i]=1;
  return bits;
}
function rasterize() {
  if (!currentImage.src) return;
  updateLabels();
  const c = controls();
  const scale = Math.min(1, c.maxWidth / currentImage.naturalWidth);
  const w = Math.max(1, Math.round(currentImage.naturalWidth * scale));
  const h = Math.max(1, Math.round(currentImage.naturalHeight * scale));
  srcCanvas.width=w; srcCanvas.height=h; outCanvas.width=w; outCanvas.height=h;
  srcCtx.imageSmoothingEnabled=true; srcCtx.imageSmoothingQuality='high'; srcCtx.fillStyle='#fff'; srcCtx.fillRect(0,0,w,h); srcCtx.drawImage(currentImage,0,0,w,h);
  const imgData=srcCtx.getImageData(0,0,w,h); const gray=prepareGray(imgData,c); let bits;
  switch(c.algorithm) {
    case 'adaptive-mean': bits=adaptiveMean(gray,w,h,c); break;
    case 'bayer4': bits=ordered(gray,w,h,c,bayer4,4); break;
    case 'bayer8': bits=ordered(gray,w,h,c,bayer8,8); break;
    case 'blue-noise': bits=blueNoise(gray,w,h,c); break;
    case 'floyd': bits=diffuse(gray,w,h,c,'floyd'); break;
    case 'atkinson': bits=diffuse(gray,w,h,c,'atkinson'); break;
    case 'stucki': bits=diffuse(gray,w,h,c,'stucki'); break;
    case 'burkes': bits=diffuse(gray,w,h,c,'burkes'); break;
    case 'sierra2': bits=diffuse(gray,w,h,c,'sierra2'); break;
    case 'sierra-lite': bits=diffuse(gray,w,h,c,'sierra-lite'); break;
    case 'edge-hybrid': bits=edgeHybrid(gray,w,h,c); break;
    default: bits=threshold(gray,w,h,c);
  }
  const res=boolToImage(bits,w,h); outCtx.putImageData(res.imageData,0,0); lastOutput=res.imageData; lastBits=bits; lastWidth=w; lastHeight=h;
  const bytesPerRow=Math.ceil(w/8), packedBytes=bytesPerRow*h, density=(res.black/bits.length*100).toFixed(1);
  $('srcSize').textContent = `${currentImage.naturalWidth}×${currentImage.naturalHeight} → ${w}×${h}`;
  $('outSize').textContent = `${density}% black`;
  const feedBytes = bytesPerRow * c.feedLines * 24;
  const totalBytes = packedBytes + feedBytes;
  $('stats').textContent = `Preset: ${currentName}
Algorithm: ${c.algorithm}
Output: ${w}×${h} px
Packed printer bytes: ${packedBytes}
With feed(${c.feedLines}): ${totalBytes} bytes
Black pixels: ${res.black} / ${bits.length} (${density}%)
90 KiB guard margin: ${92160 - totalBytes} bytes`;
}
function loadImage(src,name) {
  const im = new Image(); im.onload=()=>{ currentImage=im; currentName=name; rasterize(); }; im.src=src;
}
function initPresets() {
  const box=$('presets'); box.innerHTML='';
  CAT_PRESETS.forEach((p,idx)=>{
    const d=document.createElement('div'); d.className='preset'; d.innerHTML=`<img src="${p.src}"><div>${p.name}</div>`;
    d.onclick=()=>{ document.querySelectorAll('.preset').forEach(x=>x.classList.remove('active')); d.classList.add('active'); loadImage(p.src,p.name); };
    box.appendChild(d); if(p.name==='r02-c02' || idx===0) setTimeout(()=>{ if(!currentImage.src) d.click(); },0);
  });
}
function handleFile(file) {
  if(!file) return; const reader=new FileReader(); reader.onload=()=>loadImage(reader.result,file.name); reader.readAsDataURL(file);
}
$('file').onchange=e=>handleFile(e.target.files[0]);
const drop=$('drop');
drop.ondragover=e=>{ e.preventDefault(); drop.classList.add('drag'); };
drop.ondragleave=()=>drop.classList.remove('drag');
drop.ondrop=e=>{ e.preventDefault(); drop.classList.remove('drag'); handleFile(e.dataTransfer.files[0]); };
['algorithm','maxWidth','threshold','brightness','contrast','gamma','strength','edgeThreshold','feedLines'].forEach(id=>$(id).addEventListener('input', rasterize));
$('apply').onclick=rasterize;
$('download').onclick=()=>{ const a=document.createElement('a'); a.download=`dither-${controls().algorithm}-${currentName}.png`; a.href=outCanvas.toDataURL('image/png'); a.click(); };
function settingsLines(c) {
  const bytesPerRow = Math.ceil(lastWidth / 8);
  const packedBytes = bytesPerRow * lastHeight;
  return [
    'ALMANACH RASTER LAB',
    `image: ${currentName}`,
    `algorithm: ${c.algorithm}`,
    `threshold: ${c.threshold}  brightness: ${c.brightness}`,
    `contrast: ${c.contrast.toFixed(2)}  gamma: ${c.gamma.toFixed(2)}`,
    `strength: ${c.strength.toFixed(2)}  edge: ${c.edgeThreshold}`,
    `bitmap: ${lastWidth}x${lastHeight}  bytes: ${packedBytes}`,
  ];
}
function makePrintCanvas(c) {
  const lines = settingsLines(c);
  const lineHeight = 15, pad = 8, gap = 8;
  const headerH = pad * 2 + lines.length * lineHeight + gap;
  const width = Math.ceil(Math.max(lastWidth, 384) / 8) * 8;
  const height = headerH + lastHeight;
  const canvas = document.createElement('canvas');
  canvas.width = width; canvas.height = height;
  const ctx = canvas.getContext('2d', { willReadFrequently:true });
  ctx.imageSmoothingEnabled = false;
  ctx.fillStyle = '#fff'; ctx.fillRect(0,0,width,height);
  ctx.fillStyle = '#000'; ctx.font = '12px Monaco, Menlo, Consolas, monospace'; ctx.textBaseline = 'top';
  let y = pad;
  for (const line of lines) { ctx.fillText(line, pad, y); y += lineHeight; }
  ctx.fillRect(pad, y + 1, width - pad*2, 1);
  const x = Math.floor((width - lastWidth) / 2);
  ctx.drawImage(outCanvas, x, headerH);
  return canvas;
}
function packCanvasWithFeed(canvas, feedLines) {
  const w = canvas.width, h = canvas.height;
  const ctx = canvas.getContext('2d', { willReadFrequently:true });
  const pixels = ctx.getImageData(0,0,w,h).data;
  const paddedWidth = Math.ceil(w/8)*8, bytesPerRow = paddedWidth/8, feedRows = feedLines*24;
  const totalHeight = h + feedRows;
  const data = new Uint8Array(bytesPerRow * totalHeight);
  for(let y=0;y<h;y++) for(let x=0;x<w;x++) {
    const i=(y*w+x)*4;
    const gray=0.299*pixels[i]+0.587*pixels[i+1]+0.114*pixels[i+2];
    if(gray < 128) data[y*bytesPerRow + (x>>3)] |= 0x80 >> (x & 7);
  }
  return { data, width:paddedWidth, height:totalHeight, bytesPerRow, contentHeight:h };
}
$('print').onclick=async()=>{
  if(!lastBits) rasterize();
  const c=controls();
  const printCanvas = makePrintCanvas(c);
  const packed=packCanvasWithFeed(printCanvas,c.feedLines);
  if(packed.data.length > 92160) { alert(`Bitmap too large: ${packed.data.length} bytes > 92160`); return; }
  const url=$('printerUrl').value.trim();
  if(!url) { alert('Set printer URL first.'); return; }
  $('print').textContent='Printing…'; $('print').disabled=true;
  try {
    const res=await fetch(url,{method:'POST',headers:{'Content-Type':'application/octet-stream','X-Width':String(packed.width),'X-Height':String(packed.height),'X-Feed':'0'},body:packed.data});
    const text=await res.text();
    $('stats').textContent += `\n\nPrinted settings header + raster image.\nPrint bitmap: ${packed.width}x${packed.height}, ${packed.data.length} bytes.\nPrint HTTP ${res.status}: ${text}`;
    if(!res.ok) alert(`Print failed: HTTP ${res.status}\n${text}`);
  } catch(err) {
    $('stats').textContent += `\n\nPrint failed: ${err.message}`;
    alert(`Print failed. If this is a CORS/private-network error, serve this lab with scripts/01-serve-raster-dither-lab.py and keep Printer URL as /api/print/bitmap.\n\n${err.message}`);
  } finally { $('print').textContent='Print to Printer'; $('print').disabled=false; }
};
updateLabels(); initPresets();
